mapper.select:
SELECT kc.id AS id, pv.project_id AS projectId, kc.project_version_id AS projectVersionId,
       kc.relative_path AS title, kc.content AS body, NULL AS sub, kc.created_at AS updatedAt
FROM knowledge_chunk kc
JOIN project_version pv ON pv.id = kc.project_version_id
JOIN project p ON p.id = pv.project_id
WHERE kc.user_id = #{userId}
  AND p.user_id = #{userId}
  AND kc.content LIKE CONCAT('%', #{keyword}, '%')
ORDER BY kc.project_version_id ASC, kc.id ASC
LIMIT #{limit}
